{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "itinerary_card",
        "highlights_card",
        "quick_actions_card",
        "sources_card"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Northwest Kyoto Temple Navigation",
        "variant": "h1"
      },
      "children": []
    },
    "itinerary_card": {
      "type": "Card",
      "props": {},
      "children": [
        "itinerary_header_stack",
        "itinerary_description",
        "itinerary_table"
      ]
    },
    "itinerary_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "itinerary_image",
        "itinerary_title_stack"
      ]
    },
    "itinerary_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Kinkaku-ji_Kyoto_Japan2.jpg/1200px-Kinkaku-ji_Kyoto_Japan2.jpg"
      },
      "children": []
    },
    "itinerary_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "itinerary_icon",
        "itinerary_title_h2"
      ]
    },
    "itinerary_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg"
      },
      "children": []
    },
    "itinerary_title_h2": {
      "type": "Text",
      "props": {
        "text": "Historical Zen Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_description": {
      "type": "Text",
      "props": {
        "text": "This route explores the UNESCO World Heritage sites of Northwest Kyoto. The schedule assumes a steady walking pace of 4 km/h and includes time for deep reflection at the rock gardens."
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "location",
            "label": "Location"
          },
          {
            "key": "arrivalTime",
            "label": "Arrival Time"
          },
          {
            "key": "durationActivity",
            "label": "Duration/Activity"
          },
          {
            "key": "departureTime",
            "label": "Departure Time"
          }
        ],
        "rows": [
          {
            "location": "Kinkaku-ji",
            "arrivalTime": "09:00 AM",
            "durationActivity": "60m Sightseeing",
            "departureTime": "10:00 AM"
          },
          {
            "location": "Transit (1.3km)",
            "arrivalTime": "10:00 AM",
            "durationActivity": "20m Walk",
            "departureTime": "10:20 AM"
          },
          {
            "location": "Ryoan-ji",
            "arrivalTime": "10:20 AM",
            "durationActivity": "50m Rock Garden",
            "departureTime": "11:10 AM"
          },
          {
            "location": "Lunch Break",
            "arrivalTime": "11:10 AM",
            "durationActivity": "45m Local Cafe",
            "departureTime": "11:55 AM"
          },
          {
            "location": "Transit (0.8km)",
            "arrivalTime": "11:55 AM",
            "durationActivity": "12m Walk",
            "departureTime": "12:07 PM"
          },
          {
            "location": "Ninna-ji",
            "arrivalTime": "12:07 PM",
            "durationActivity": "60m Pagoda/Gardens",
            "departureTime": "01:07 PM"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "location",
        "highlightColumns": [
          "arrivalTime",
          "departureTime"
        ]
      },
      "children": []
    },
    "highlights_card": {
      "type": "Card",
      "props": {},
      "children": [
        "highlights_header_stack",
        "kinkakuji_highlight_stack",
        "ryoanji_highlight_stack",
        "ninnaji_highlight_stack"
      ]
    },
    "highlights_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "highlights_image",
        "highlights_title_stack"
      ]
    },
    "highlights_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Ryoanji_Rock_Garden_Kyoto_Japan.jpg/1200px-Ryoanji_Rock_Garden_Kyoto_Japan.jpg"
      },
      "children": []
    },
    "highlights_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "highlights_icon",
        "highlights_title_h2"
      ]
    },
    "highlights_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg"
      },
      "children": []
    },
    "highlights_title_h2": {
      "type": "Text",
      "props": {
        "text": "Landmark Highlights",
        "variant": "h2"
      },
      "children": []
    },
    "kinkakuji_highlight_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "kinkakuji_label",
        "kinkakuji_desc"
      ]
    },
    "kinkakuji_label": {
      "type": "Text",
      "props": {
        "text": "Kinkaku-ji",
        "variant": "label"
      },
      "children": []
    },
    "kinkakuji_desc": {
      "type": "Text",
      "props": {
        "text": "The Golden Pavilion, covered in gold leaf, reflecting in the Kyoko-chi pond."
      },
      "children": []
    },
    "ryoanji_highlight_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ryoanji_label",
        "ryoanji_desc"
      ]
    },
    "ryoanji_label": {
      "type": "Text",
      "props": {
        "text": "Ryoan-ji",
        "variant": "label"
      },
      "children": []
    },
    "ryoanji_desc": {
      "type": "Text",
      "props": {
        "text": "Japan's most famous Zen rock garden, consisting of 15 carefully placed stones."
      },
      "children": []
    },
    "ninnaji_highlight_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ninnaji_label",
        "ninnaji_desc"
      ]
    },
    "ninnaji_label": {
      "type": "Text",
      "props": {
        "text": "Ninna-ji",
        "variant": "label"
      },
      "children": []
    },
    "ninnaji_desc": {
      "type": "Text",
      "props": {
        "text": "Known for its five-story pagoda and the late-blooming Omuro cherry trees."
      },
      "children": []
    },
    "quick_actions_card": {
      "type": "Card",
      "props": {},
      "children": [
        "quick_actions_title_h2",
        "quick_actions_button_stack"
      ]
    },
    "quick_actions_title_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_button_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "map_button",
        "temple_info_button"
      ]
    },
    "map_button": {
      "type": "Button",
      "props": {
        "label": "Open Walking Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/dir/Kinkaku-ji/Ryoan-ji/Ninna-ji/"
          }
        }
      },
      "children": []
    },
    "temple_info_button": {
      "type": "Button",
      "props": {
        "label": "Temple Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ryoanji.jp/smph/eng/"
          }
        }
      },
      "children": []
    },
    "sources_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sources_title_h2",
        "sources_button_stack"
      ]
    },
    "sources_title_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_button_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ryoanji_source_button",
        "ninnaji_source_button"
      ]
    },
    "ryoanji_source_button": {
      "type": "Button",
      "props": {
        "label": "Ryoan-ji Official"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ryoanji.jp/en/"
          }
        }
      },
      "children": []
    },
    "ninnaji_source_button": {
      "type": "Button",
      "props": {
        "label": "Ninna-ji Official"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ninnaji.jp/en/"
          }
        }
      },
      "children": []
    }
  }
}
